#!/usr/bin/env python3
"""Exercise the deferred reopen state machine using minimal server stubs."""
import os, pathlib, subprocess, tempfile
root=pathlib.Path(__file__).resolve().parents[2]
prefix=root/'tools/elytrix-airdrop/src/ru/rooyzee/elytrixairdrop/patch'
files={
'org/bukkit/event/Listener.java':'package org.bukkit.event; public interface Listener {}',
'org/bukkit/event/EventPriority.java':'package org.bukkit.event; public enum EventPriority {MONITOR}',
'org/bukkit/event/EventHandler.java':'package org.bukkit.event; import java.lang.annotation.*; @Retention(RetentionPolicy.RUNTIME) public @interface EventHandler {EventPriority priority() default EventPriority.MONITOR;}',
'org/bukkit/event/inventory/InventoryType.java':'package org.bukkit.event.inventory; public enum InventoryType {CRAFTING,CHEST}',
'org/bukkit/inventory/Inventory.java':'package org.bukkit.inventory; import org.bukkit.event.inventory.InventoryType; public class Inventory {public InventoryType type; public Inventory(InventoryType t){type=t;} public InventoryType getType(){return type;}}',
'org/bukkit/inventory/InventoryView.java':'package org.bukkit.inventory; public class InventoryView {public Inventory top; public InventoryView(Inventory v){top=v;} public Inventory getTopInventory(){return top;}}',
'org/bukkit/Location.java':'package org.bukkit; public class Location {public Object world; public double dist; public Location(Object w,double d){world=w;dist=d;} public Object getWorld(){return world;} public double distanceSquared(Location other){return dist;}}',
'org/bukkit/entity/Player.java':'''package org.bukkit.entity; import java.util.*; import org.bukkit.*; import org.bukkit.inventory.*; import org.bukkit.event.inventory.InventoryType; public class Player {public boolean online=true,dead=false; public Object world=new Object();public double distance=0; public InventoryView view=new InventoryView(new Inventory(InventoryType.CRAFTING)); public int opens;public UUID id=UUID.randomUUID(); public Runnable duringOpen;public boolean isOnline(){return online;} public boolean isDead(){return dead;} public UUID getUniqueId(){return id;} public Object getWorld(){return world;} public Location getLocation(){return new Location(world,distance);} public InventoryView getOpenInventory(){return view;} public InventoryView openInventory(Inventory i){opens++;if(duringOpen!=null)duringOpen.run();view=new InventoryView(i);return view;}public void sendMessage(String s){} }''',
'org/bukkit/event/inventory/InventoryCloseEvent.java':'''package org.bukkit.event.inventory; import org.bukkit.entity.Player; import org.bukkit.inventory.Inventory; public class InventoryCloseEvent {public enum Reason {PLAYER,PLUGIN,OPEN_NEW,TELEPORT} private Player p;private Inventory i;private Reason r;public InventoryCloseEvent(Player p,Inventory i,Reason r){this.p=p;this.i=i;this.r=r;}public Player getPlayer(){return p;}public Inventory getInventory(){return i;}public Reason getReason(){return r;}}''',
'org/bukkit/event/player/PlayerQuitEvent.java':'package org.bukkit.event.player; import org.bukkit.entity.Player; public class PlayerQuitEvent {private Player p;public PlayerQuitEvent(Player p){this.p=p;}public Player getPlayer(){return p;}}',
'org/bukkit/Bukkit.java':'''package org.bukkit; import java.util.*; import org.bukkit.event.Listener; public class Bukkit {public static Scheduler scheduler=new Scheduler();public static Manager manager=new Manager();public static Scheduler getScheduler(){return scheduler;}public static Manager getPluginManager(){return manager;} public static class Scheduler {public List<Runnable> tasks=new ArrayList<>(); public void runTaskLater(Object p,Runnable r,long delay){if(delay!=2)throw new AssertionError("delay");tasks.add(r);}public void run(){List<Runnable> copy=new ArrayList<>(tasks);tasks.clear();copy.forEach(Runnable::run);}}public static class Manager {public Listener listener;public void registerEvents(Listener l,Object p){listener=l;}}}''',
'ru/rooyzee/elytrixairdrop/utils/ColorUtil.java':'package ru.rooyzee.elytrixairdrop.utils; public class ColorUtil {public static String colorize(String s){return s;}}',
'ru/rooyzee/elytrixairdrop/airdrops/Airdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops; public enum Airdrop {PEACEFUL,FIRE}',
'ru/rooyzee/elytrixairdrop/airdrops/ActiveAirdrop.java':'''package ru.rooyzee.elytrixairdrop.airdrops; import java.util.*; import org.bukkit.*; import org.bukkit.inventory.*; import org.bukkit.event.inventory.InventoryType; public class ActiveAirdrop {public Inventory lootInventory=new Inventory(InventoryType.CHEST); public boolean looted=false;public List<String> pendingLoot=new ArrayList<>(List.of("one"));public Location chestLoc;public Airdrop getType(){return Airdrop.PEACEFUL;} }''',
'ru/rooyzee/elytrixairdrop/Main.java':'''package ru.rooyzee.elytrixairdrop; import java.util.logging.*; import ru.rooyzee.elytrixairdrop.airdrops.*; public class Main {public Manager manager=new Manager();public Manager getAirdropManager(){return manager;}public Logger getLogger(){return Logger.getAnonymousLogger();}public static class Manager {public ActiveAirdrop active;public ActiveAirdrop getActive(){return active;}}}''',
'TestChest.java':'''import org.bukkit.*; import org.bukkit.entity.*; import org.bukkit.event.inventory.*; import org.bukkit.inventory.*; import ru.rooyzee.elytrixairdrop.*; import ru.rooyzee.elytrixairdrop.airdrops.*; import ru.rooyzee.elytrixairdrop.patch.*; public class TestChest {static void check(boolean v,String message){if(!v)throw new AssertionError(message);}static void close(PeacefulChest l,Player p,ActiveAirdrop a,InventoryCloseEvent.Reason r){l.close(new InventoryCloseEvent(p,a.lootInventory,r));}public static void main(String[] args){Main plugin=new Main();Player p=new Player();ActiveAirdrop a=new ActiveAirdrop();a.chestLoc=new Location(p.world,0);plugin.manager.active=a;PeacefulChest.install(plugin);PeacefulChest l=(PeacefulChest)Bukkit.manager.listener;
 close(l,p,a,InventoryCloseEvent.Reason.PLUGIN);check(Bukkit.scheduler.tasks.isEmpty(),"plugin close");close(l,p,a,InventoryCloseEvent.Reason.PLAYER);close(l,p,a,InventoryCloseEvent.Reason.PLAYER);check(Bukkit.scheduler.tasks.size()==1 && p.opens==0,"only deferred one task");p.duringOpen=()->close(l,p,a,InventoryCloseEvent.Reason.PLAYER);Bukkit.scheduler.run();check(p.opens==1&&Bukkit.scheduler.tasks.isEmpty(),"reentrant close");p.duringOpen=null;
 p.view=new InventoryView(new Inventory(InventoryType.CRAFTING));close(l,p,a,InventoryCloseEvent.Reason.PLAYER);a.pendingLoot.clear();Bukkit.scheduler.run();check(p.opens==1,"last wave");a.pendingLoot.add("two");
 p.view=new InventoryView(new Inventory(InventoryType.CRAFTING));close(l,p,a,InventoryCloseEvent.Reason.PLAYER);plugin.manager.active=null;Bukkit.scheduler.run();check(p.opens==1,"stopped");plugin.manager.active=a;
 l.quit(new org.bukkit.event.player.PlayerQuitEvent(p));p.view=new InventoryView(new Inventory(InventoryType.CRAFTING));close(l,p,a,InventoryCloseEvent.Reason.PLAYER);p.view=new InventoryView(new Inventory(InventoryType.CHEST));Bukkit.scheduler.run();check(p.opens==1,"other gui");
 p.view=new InventoryView(new Inventory(InventoryType.CRAFTING));close(l,p,a,InventoryCloseEvent.Reason.PLAYER);p.distance=37;Bukkit.scheduler.run();check(p.opens==1,"distance");p.distance=0;
 l.quit(new org.bukkit.event.player.PlayerQuitEvent(p));for(int i=0;i<6;i++){p.view=new InventoryView(new Inventory(InventoryType.CRAFTING));close(l,p,a,InventoryCloseEvent.Reason.PLAYER);Bukkit.scheduler.run();}check(p.opens==5,"bounded attempts "+p.opens);System.out.println("Peaceful stub test: deferred, reentrant, final wave, stop, other GUI, distance and bounded loop OK");}}'''
}
java=os.environ['JAVA'];ecj=os.environ['ECJ']
with tempfile.TemporaryDirectory() as tmp:
 p=pathlib.Path(tmp)
 for name,content in files.items():
  f=p/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content)
 out=p/'classes';out.mkdir()
 subprocess.run([java,'-jar',ecj,'-21','-proc:none','-nowarn','-d',str(out),*[str(p/x) for x in files],str(prefix/'PeacefulChest.java'),str(prefix/'ReopenGuard.java')],check=True)
 subprocess.run([java,'-Xverify:all','-cp',str(out),'TestChest'],check=True)
